// Muxes real H.264 + AAC (generated by ffmpeg) with our muxer, then verifies with ffprobe/ffmpeg.
import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Mp4Muxer } from '../src/export/mp4mux.js';

const hasFfmpeg = spawnSync('ffmpeg', ['-version']).status === 0;

function splitAnnexB(buf) {
  const nals = [];
  let i = 0, start = -1;
  while (i + 3 <= buf.length) {
    if (buf[i] === 0 && buf[i + 1] === 0 && (buf[i + 2] === 1 || (buf[i + 2] === 0 && buf[i + 3] === 1))) {
      if (start >= 0) nals.push(buf.subarray(start, i));
      const sc = buf[i + 2] === 1 ? 3 : 4;
      start = i + sc;
      i += sc;
    } else i++;
  }
  if (start >= 0) nals.push(buf.subarray(start));
  return nals;
}
const lenPrefixed = (nals) => {
  const out = new Uint8Array(nals.reduce((a, n) => a + 4 + n.length, 0));
  const dv = new DataView(out.buffer);
  let o = 0;
  for (const n of nals) { dv.setUint32(o, n.length); out.set(n, o + 4); o += 4 + n.length; }
  return out;
};

test('muxes H.264 + AAC into a valid, decodable MP4', { skip: !hasFfmpeg }, async () => {
  const dir = mkdtempSync(join(tmpdir(), 'filmly-mux-'));
  try {
    const FPS = 30, N = 60;
    execFileSync('ffmpeg', ['-v', 'error', '-f', 'lavfi', '-i', `testsrc=size=640x360:rate=${FPS}`, '-frames:v', String(N), '-c:v', 'libx264', '-bf', '0', '-g', '15', '-pix_fmt', 'yuv420p', '-x264-params', 'aud=1', '-f', 'h264', join(dir, 'v.h264')]);
    execFileSync('ffmpeg', ['-v', 'error', '-f', 'lavfi', '-i', 'sine=frequency=440:sample_rate=48000', '-t', '2', '-ac', '2', '-c:a', 'aac', '-f', 'adts', join(dir, 'a.aac')]);

    // --- video access units ---
    const nals = splitAnnexB(new Uint8Array(readFileSync(join(dir, 'v.h264'))));
    let sps, pps;
    const aus = [];
    let cur = null;
    for (const n of nals) {
      const type = n[0] & 31;
      if (type === 9) { cur = { nals: [], key: false }; aus.push(cur); continue; }
      if (type === 7) sps = n; else if (type === 8) pps = n;
      if (type === 5) cur.key = true;
      if (type !== 7 && type !== 8 && cur) cur.nals.push(n);
    }
    assert.equal(aus.length, N);
    const avcC = new Uint8Array([1, sps[1], sps[2], sps[3], 0xff, 0xe1, sps.length >> 8, sps.length & 255, ...sps, 1, pps.length >> 8, pps.length & 255, ...pps]);

    // --- AAC ADTS frames ---
    const adts = new Uint8Array(readFileSync(join(dir, 'a.aac')));
    const frames = [];
    for (let p = 0; p + 7 < adts.length;) {
      const len = ((adts[p + 3] & 3) << 11) | (adts[p + 4] << 3) | (adts[p + 5] >> 5);
      const hdr = (adts[p + 1] & 1) ? 7 : 9;
      frames.push(adts.subarray(p + hdr, p + len));
      p += len;
    }
    const prof = (adts[2] >> 6) + 1, sf = (adts[2] >> 2) & 15, chan = ((adts[2] & 1) << 2) | (adts[3] >> 6);
    const asc = new Uint8Array([(prof << 3) | (sf >> 1), ((sf & 1) << 7) | (chan << 3)]);

    const mux = new Mp4Muxer({ video: { codec: 'avc', width: 640, height: 360 }, audio: { codec: 'aac', sampleRate: 48000, channels: 2 } });
    aus.forEach((au, i) => mux.addRaw('video', lenPrefixed(au.nals), Math.round((i * 1e6) / FPS), Math.round(1e6 / FPS), au.key, i === 0 ? avcC : null));
    frames.forEach((f, i) => mux.addRaw('audio', f, Math.round((i * 1024 * 1e6) / 48000), Math.round((1024 * 1e6) / 48000), true, i === 0 ? asc : null));
    const blob = mux.finalize();
    const out = join(dir, 'out.mp4');
    {
      const ab = await blob.arrayBuffer();
      writeFileSync(out, new Uint8Array(ab));
      const probe = JSON.parse(execFileSync('ffprobe', ['-v', 'error', '-count_frames', '-show_streams', '-show_format', '-of', 'json', out]).toString());
      const v = probe.streams.find((s) => s.codec_type === 'video');
      const a = probe.streams.find((s) => s.codec_type === 'audio');
      assert.equal(v.codec_name, 'h264');
      assert.equal(v.width, 640);
      assert.equal(v.height, 360);
      assert.equal(Number(v.nb_read_frames), N);
      assert.equal(v.avg_frame_rate, '30/1');
      assert.equal(a.codec_name, 'aac');
      assert.equal(a.channels, 2);
      assert.equal(a.sample_rate, '48000');
      // full decode must succeed with zero errors
      const dec = spawnSync('ffmpeg', ['-v', 'error', '-i', out, '-f', 'null', '-']);
      assert.equal(dec.status, 0, dec.stderr.toString());
      assert.equal(dec.stderr.toString().trim(), '');
      // moov before mdat (faststart)
      const bytes = new Uint8Array(ab);
      const find = (s) => { const t = Buffer.from(s); return Buffer.from(bytes).indexOf(t); };
      assert.ok(find('moov') < find('mdat'), 'moov should precede mdat');
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test('240 fps timestamps stay exact (no duration drift)', () => {
  const mux = new Mp4Muxer({ video: { codec: 'avc', width: 64, height: 64 } });
  const N = 480;
  for (let i = 0; i < N; i++) mux.addRaw('video', new Uint8Array([0, 0, 0, 1, 0x65]), Math.round((i * 1e6) / 240), Math.round(1e6 / 240), i % 120 === 0, i === 0 ? new Uint8Array([1, 100, 0, 51, 255, 225, 0, 0, 1, 0, 0]) : null);
  mux.finalize();
  const t = mux.vtrack;
  assert.equal(t.totalTicks, 2 * 90000); // exactly 2.000 s
  assert.ok(t.samples.every((s) => s.durTicks === 375));
});
